class LmdbAdjacencyRangePlannerTest {

	@TempDir
	Path directory;

	@ParameterizedTest
	@ValueSource(strings = { "psoc", "posc", "spoc", "opsc" })
	void splitsRespectLiveDeltaStateUnsignedOrderAndResidualContexts(String order) throws Exception {
		try (TripleStore store = store()) {
			seed(store);
			mutate(store);
			try (Txn txn = store.getTxnManager().createReadTxn()) {
				for (long context : new long[] { -1, 7 }) {
					long stamp = txn.lockManager().readLock();
					try {
						LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn.get());
						List<Split> splits = new LmdbAdjacencyRangePlanner(adjacency)
								.plan(txn.get(), order, -1, -1, -1, context, true, 8, 4);
						assertThat(splits).as("order=%s, context=%s", order, context).hasSizeBetween(2, 7);
						List<long[]> rows = read(adjacency, txn, order, -1, -1, -1, context);
						assertActualBoundaries(rows, splits, order);
					} finally {
						txn.lockManager().unlockRead(stamp);
					}
				}
			}
		}
	}

	@Test
	void heavySingleRowUsesFullKeySplitsWhileWholeRowPrefixRemainsUnsplittable() throws Exception {
		try (TripleStore store = store()) {
			store.startTransaction();
			for (int i = 0; i < 2048; i++) {
				long neighbor = i < 1024 ? i + 1 : Long.MIN_VALUE + i - 1024;
				store.storeTriple(10, 20, neighbor, 0, true);
			}
			store.commit();
			try (Txn txn = store.getTxnManager().createReadTxn()) {
				long stamp = txn.lockManager().readLock();
				try {
					LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn.get());
					LmdbAdjacencyRangePlanner planner = new LmdbAdjacencyRangePlanner(adjacency);
					assertThat(planner.plan(txn.get(), "psoc", -1, 20, -1, -1, true, 8, 2)).isEmpty();
					List<Split> splits = planner.plan(txn.get(), "psoc", -1, 20, -1, -1, true, 8, 4);
					assertThat(splits).hasSize(7).allMatch(Split::startsWithContinuation);
					assertActualBoundaries(read(adjacency, txn, "psoc", -1, 20, -1, -1), splits, "psoc");
				} finally {
					txn.lockManager().unlockRead(stamp);
				}
			}
		}
	}

	@Test
	void wholePredicatePrefixesAndRowsHeldOnlyInDeltasHaveExactBoundaries() throws Exception {
		try (TripleStore store = store()) {
			seed(store);
			mutate(store);
			try (Txn txn = store.getTxnManager().createReadTxn()) {
				long stamp = txn.lockManager().readLock();
				try {
					LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn.get());
					LmdbAdjacencyRangePlanner planner = new LmdbAdjacencyRangePlanner(adjacency);
					List<Split> predicates = planner.plan(txn.get(), "psoc", -1, -1, -1, -1, true, 8, 1);
					assertThat(predicates).hasSize(1);
					assertThat(predicates.getFirst().quad()[1]).isEqualTo(20);
					assertThat(predicates.getFirst().startsWithContinuation()).isFalse();
					List<Split> deltaRow = planner.plan(txn.get(), "psoc", 200, 10, -1, -1, true, 8, 4);
					assertThat(deltaRow).hasSize(1);
					assertThat(deltaRow.getFirst().quad()).containsExactly(200, 10, Long.MIN_VALUE + 1, 7);
					assertThat(deltaRow.getFirst().startsWithContinuation()).isTrue();
				} finally {
					txn.lockManager().unlockRead(stamp);
				}
			}
		}
	}

	@Test
	void pinnedSnapshotPlansRetainTheirOriginalPagesMetadataAndDeltas() throws Exception {
		try (TripleStore store = store()) {
			seed(store);
			try (Txn txn = store.getTxnManager().createReadTxnPinned(store::getDataRevision)) {
				List<String> before = planStrings(txn);
				mutate(store);
				assertThat(planStrings(txn)).containsExactlyElementsOf(before);
			}
		}
	}

	private static List<String> planStrings(Txn txn) throws Exception {
		long stamp = txn.lockManager().readLock();
		try {
			LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn.get());
			return new LmdbAdjacencyRangePlanner(adjacency).plan(txn.get(), "posc", -1, -1, -1, -1, true, 8, 4)
					.stream()
					.map(split -> Arrays.toString(split.quad()) + "/" + split.startsWithContinuation())
					.toList();
		} finally {
			txn.lockManager().unlockRead(stamp);
		}
	}

	private static List<long[]> read(LmdbPersistentAdjacency adjacency, Txn txn, String order,
			long subject, long predicate, long object, long context) throws Exception {
		List<long[]> rows = new ArrayList<>();
		try (RecordIterator records = adjacency.scan(txn.get(), subject, predicate, object, context, true, order)) {
			long[] row;
			while ((row = records.next()) != null) {
				rows.add(row.clone());
			}
		}
		return rows;
	}

	private static void assertActualBoundaries(List<long[]> rows, List<Split> splits, String order) {
		int previousPosition = 0;
		int rowComponent = order.equals("posc") || order.equals("opsc") ? 2 : 0;
		for (Split split : splits) {
			long[] quad = split.quad();
			int position = -1;
			for (int i = 0; i < rows.size(); i++) {
				if (Arrays.equals(rows.get(i), quad)) {
					position = i;
					break;
				}
			}
			assertThat(position).as("each ordered split is a live matching quad after the previous boundary")
					.isGreaterThan(previousPosition);
			long[] predecessor = rows.get(position - 1);
			assertThat(split.startsWithContinuation())
					.isEqualTo(predecessor[1] == quad[1] && predecessor[rowComponent] == quad[rowComponent]);
			previousPosition = position;
		}
	}

	private TripleStore store() throws Exception {
		return new TripleStore(directory.toFile(), new LmdbStoreConfig(), null);
	}

	private static void seed(TripleStore store) throws Exception {
		store.startTransaction();
		for (long predicate : new long[] { 10, 20 }) {
			for (long subject = 1; subject <= 150; subject++) {
				long object = subject % 3 == 0 ? Long.MIN_VALUE + subject : 1000 + subject;
				store.storeTriple(subject, predicate, object, subject % 5 == 0 ? 7 : 0, true);
			}
		}
		store.commit();
	}

	private static void mutate(TripleStore store) throws Exception {
		store.startTransaction();
		store.removeTriplesByContext(1, 10, 1001, 0, true, ignored -> {
		});
		store.removeTriplesByContext(75, 10, Long.MIN_VALUE + 75, 7, true, ignored -> {
		});
		store.storeTriple(200, 10, Long.MAX_VALUE, 7, true);
		store.storeTriple(200, 10, Long.MIN_VALUE + 1, 7, true);
		store.storeTriple(201, 10, Long.MIN_VALUE, 7, true);
		store.storeTriple(202, 20, -2, 7, true);
		store.commit();
	}
}
